_RAW = "{\n  \"services\": {\n    \"Citizenship Certificate Copy\": {\n      \"title\": \"नागरिकता प्रमाणपत्रको प्रतिलिपि\",\n      \"category\": \"पहिचान\",\n      \"description\": \"नेपालको आधारभूत पहिचान दस्तावेज, जिल्ला प्रशासन कार्यालय (DAO) द्वारा तपाईंको वार्ड कार्यालयको सिफारिसमा जारी गरिएको। NID, पासपोर्ट, ड्राइभिङ लाइसेन्स, बैंकिङ, र मतदानको लागि आवेदन गर्नु अघि आवश्यक।\",\n      \"guidance\": \"अवलोकन\\nनागरिकता प्रमाणपत्र नेपालको आधारभूत पहिचान दस्तावेज हो। यो NID, पासपोर्ट, ड्राइभिङ लाइसेन्स, बैंक खाता खोल्ने, सम्पत्ति लेनदेन, र मतदानको लागि आवेदन दिने अघि आवश्यक पर्छ। यो जिल्ला प्रशासन कार्यालय (DAO) द्वारा मुख्य जिल्ला अधिकृतको अन्तर्गत, तपाईंको वार्ड कार्यालयको सिफारिसमा जारी गरिन्छ। मुख्य वर्गीकरणहरू: वंश अनुसार (मानक मार्ग), जन्म अनुसार, प्राकृतिकरण, र सम्मानजनक।\\n\\nपूर्वापेक्षाहरू\\n- तपाईं १६ वर्ष वा सोभन्दा माथि हुनु पर्छ (वंश अनुसार नागरिकता लागि)।\\n- कम्तिमा एक अभिभावकले नेपाली नागरिकता धारण गर्नुपर्छ।\\n- स्थायी बासस्थानले तपाईंले आवेदन दिने वार्ड कार्यालय/DAO को अधिकारक्षेत्रभित्र पर्नुपर्छ; यदि तपाईं अर्को जिल्लाबाट सरेको हुनुहुन्छ भने सरुवा प्रमाणपत्र (Saruwa) आवश्यक पर्छ।\\n- जन्म दर्ता नाम र जन्म मिति तपाईंका अभिभावकको नागरिकता विवरणसँग पूर्ण रूपमा मिल्नुपर्छ।\\n\\nआवश्यक कागजातहरू\\n- निर्दिष्ट आवेदन फारम (Schedule-1), वार्ड कार्यालयमा उपलब्ध र प्रमाणित गरिएको\\n- दुबै अभिभावकको मूल नागरिकता प्रमाणपत्र + फोटोकपीहरू\\n- जन्म दर्ता प्रमाणपत्र\\n- स्कूल छोड्ने/SEE प्रमाणपत्र वा चरित्र प्रमाणपत्र\\n- अभिभावकको विवाह प्रमाणपत्र\\n- वार्ड कार्यालयको सिफारिस पत्र\\n- दुई हालैको पासपोर्ट आकारको फोटो\\n- NPR 10 राजस्व टाँस\\n- पहिले नै नागरिकता धारण गर्ने वयस्क रक्त सम्बन्धी वा वार्ड बासिन्दा (गवाही)\\n- सरुवा प्रमाणपत्र (Saruwa), केवल गृह जिल्ला बाहिर आवेदन गर्दा\\n\\nस्टेप-बाइ-स्टेप प्रक्रिया\\n1. पहिले आफ्नो अभिलेख मिलाउनुहोस् — दर्ता गर्नु अघि वार्ड कार्यालयमा नाम/जन्म मिति मिलान नहुनु भएको त्रुटि सुधार्नुहोस्।\\n2. आफ्नो स्थानीय वार्ड कार्यालयमा अभिभावकको नागरिकता प्रमाणपत्र, आफ्नो जन्म दर्ता, विद्यालय प्रमाणपत्र, अभिभावकको विवाह प्रमाणपत्र, र फोटोहरू सहित जानुहोस्।\\n3. वार्ड कार्यालयबाट तपाईंको पहिचान र बासस्थान प्रमाणित गर्ने सिफारिस पत्र प्राप्त गर्नुहोस्।\\n4. Schedule-1 आवेदन फारम भर्नुहोस् र राजस्व टाँस (revenue stamp) जोड्नुहोस्।\\n5. आवेदन DAO को नागरिकता विभागमा आफ्नो वयस्क साक्षीको साथ पेश गर्नुहोस्।\\n6. स्पट इन्क्वायरी/पुलिस प्रमाणिकरण (Sarjaamin) बोलाइएमा प्रमाणिकरणमा उपस्थित हुनुहोस्।\\n7. आफ्नो प्रमाणपत्र प्राप्त गर्नुहोस् — प्रायः सोही दिन वा केही कार्यदिवसभित्र।\\n\\nशुल्कहरू\\n- पहिलो पटक वंश प्रमाणपत्र: लगभग NPR 10 (revenue stamp)\\n- डुप्लिकेट/प्रतिस्थापन प्रमाणपत्र: लगभग NPR 13\\n- शुल्कहरू जिल्ला अनुसार थोरै फरक हुन सक्छ — आफ्नो स्थानीय DAO मा पुष्टि गर्नुहोस्।\\n\\nप्रक्रिया समय\\n- सरल वंश आवेदनहरूका लागि सोही दिन देखि केही कार्यदिवससम्म।\\n- नागरिकता/सम्मानित केसहरू गृह मन्त्रालय र क्याबिनेट मार्फत जान्छन् र केही महिना लाग्न सक्छ।\\n\\nआधिकारिक स्रोतहरू\\n- Ministry of Home Affairs: https://moha.gov.np\\n- Nepal Law Commission (Citizenship Act 2063): https://lawcommission.gov.np\\n- तपाईंको स्थानीय जिल्ला प्रशासन कार्यालय (DAO)\"\n    },\n    \"NID Registration\": {\n      \"title\": \"NID दर्ता\",\n      \"category\": \"पहिचान\",\n      \"description\": \"बायोमेट्रिक नेशनल आइडेन्टिटी कार्ड DoNIDCR द्वारा जारी गरिएको, अनन्य 10-अङ्कीय NIN सहित। e-passport आवेदन, बैंकिङ, SIM दर्ता, तथा कम्पनी दर्ताका लागि अनिवार्य।\",\n      \"guidance\": \"अवलोकन\\nNID भनेको राष्ट्रिय परिचयपत्र तथा नागरिक दर्ता विभाग (DoNIDCR) द्वारा जारी गरिएको बायोमेट्रिक स्मार्ट कार्ड हो। यसमा तपाईंको फोटो, औँठा छाप, आइरिस स्क्यान, र अनन्य १०-अङ्कीय राष्ट्रिय परिचय नम्बर (NIN) संग्रहित हुन्छ। २०२६ सम्म, e‑passport आवेदन, बैंकिङ, SIM दर्ता, तथा कम्पनी दर्ताका लागि NID/NIN अनिवार्य छ। यसले अन्ततः कागजको नागरिकता प्रमाणपत्रलाई प्रतिस्थापन गर्ने लक्ष्य राखेको छ।\\n\\nपूर्वापेक्षाहरू\\n- १६ वर्ष वा सोभन्दा माथि उमेरको नेपाली नागरिक हुनुपर्छ।\\n- वैध नागरिकता प्रमाणपत्र (NID यसमा आधारित जारी गरिन्छ) धारण गर्नुपर्छ।\\n- नेपालमा बसोबास गर्ने विदेशीहरू योग्य छैनन्।\\n\\nआवश्यक कागजातहरू\\n- मूल नागरिकता प्रमाणपत्र (र फोटोकपी)\\n- यदि लागू भएमा माइग्रेशन प्रमाणपत्र\\n- यदि विवाहित हुनुहुन्छ भने वैवाहिक प्रमाणपत्र\\n- यदि लागू भएमा जीवनसाथीको मृत्यु प्रमाणपत्र\\n- हालको पासपोर्ट आकारको फोटो (ब्याकअप; बायोमेट्रिक फोटो प्रत्यक्ष रूपमा कैप्चर गरिन्छ)\\n- OTP प्रमाणीकरणको लागि मोबाइल नम्बर\\n\\nSTEP-BY-STEP PROCEDURE\\n1. DoNIDCR पूर्व‑दर्ता पोर्टल (https://donidcr.gov.np) मा जानुहोस् र आफ्नो मोबाइल नम्बर प्रयोग गरी लग‑इन गर्नुहोस् वा खाता बनाउनुहोस्।\\n2. SMS मार्फत पठाइएको OTP द्वारा आफ्नो नम्बर प्रमाणित गर्नुहोस्।\\n3. ‘नयाँ दर्ता’ सुरु गर्नुहोस् र व्यक्तिगत विवरणहरू भर्नुहोस् — ती तपाईंको नागरिकता प्रमाणपत्रसँग पूर्ण रूपमा मिल्नुपर्छ।\\n4. समर्थन कागजातहरू अपलोड गर्नुहोस् (नागरिकता प्रमाणपत्र, लागू भएमा विवाह प्रमाणपत्र)।\\n5. आफ्नो दर्ता केन्द्र चयन गर्नुहोस् (सामान्यतया तपाईंको स्थानीय DAO) र नियुक्ति मिति छान्नुहोस्।\\n6. आफ्नो पूर्व‑दर्ता/टोकन स्लिप प्रिन्ट गर्नुहोस् र मूल कागजातहरूसँग राख्नुहोस्।\\n7. व्यक्तिगत रूपमा आफ्नो नियुक्तिमा उपस्थित हुनुहोस् — अनुहार र कान स्पष्ट देखिनु आवश्यक छ (भारी मेकअप, औँठी, टोपी, वा अनुहार ढाक्ने वस्तु नलगाउनुहोस्)।\\n8. बायोमेट्रिक क्याप्चर पूरा गर्नुहोस्: फोटो, सबै दशऔँला फिंगरप्रिन्ट, आइरिस स्क्यान, र डिजिटल हस्ताक्षर।\\n9. त्रुटि भएमा तुरुन्तै बायोमेट्रिक रिपोर्ट जाँच गर्नुहोस्।\\n10. अस्थायी NIN पुष्टि प्राप्त गर्नुहोस्, कार्ड प्रिन्ट हुँदै गर्दा तुरुन्तै प्रयोग गर्न सकिन्छ।\\n11. सूचना प्राप्त भएपछि आफ्नो भौतिक कार्ड सङ्कलन गर्नुहोस् (ब्याकलग अनुसार हप्तादेखि महिनासम्म)।\\n12. इन्टरनेट पहुँच छैन? कुनै पनि DAO मा सिधै जानुहोस् — कर्मचारीहरूले साइटमै फारम भर्नेछन् (लामो पङ्क्ति हुन सक्छ)।\\n\\nFEES\\n- First-time enrollment: free\\n- Replacement card (lost/damaged): approx. NPR 500\\n\\nPROCESSING TIME\\n- Online pre-enrollment: same day\\n- Biometric appointment: based on centre availability\\n- Physical card delivery: a few weeks to a few months (large national backlog)\\n\\nOFFICIAL RESOURCES\\n- DoNIDCR: https://donidcr.gov.np\\n- Nagarik App (for digital NID access) on Google Play / App Store\"\n    },\n    \"E-Passport Apply\": {\n      \"title\": \"इ-पासपोर्ट आवेदन\",\n      \"category\": \"पहिचान\",\n      \"description\": \"नेपालको ICAO‑अनुपालन बायोमेट्रिक इ‑पासपोर्ट, पासपोर्ट विभागद्वारा जारी। अनलाइन आवेदन गर्नुहोस्, त्यसपछि बायोमेट्रिकको लागि व्यक्तिगत अपोइन्टमेन्टमा पासपोर्ट विभाग, कुनै पनि DAO, वा विदेशको दूतावासमा उपस्थित हुनुहोस्।\",\n      \"guidance\": \"अवलोकन\\nनेपालको बायोमेट्रिक ई-पासपोर्ट विदेश मन्त्रालय अन्तर्गत पासपोर्ट विभागले जारी गर्दछ, पासपोर्ट ऐन २०७६ र पासपोर्ट नियमावली २०७७ द्वारा नियमन गरिएको छ। यो ICAO Doc 9303 मानकसँग अनुरूप छ। आवेदनहरू पासपोर्ट विभाग (काठमाडौँ), कुनै पनि जिल्ला प्रशासन कार्यालय (DAO), वा विदेशमा रहेका नेपाली दूतावास तथा कन्सुलेटहरूमा गर्न सकिन्छ।\\n\\nपूर्वापेक्षाहरू\\n- नेपाली नागरिक हुनुपर्छ र वैध नागरिकता प्रमाणपत्र हुनु पर्दछ।\\n- राष्ट्रिय पहिचान नम्बर (NID/NIN) हुनुपर्छ — आवेदन तथा नवीकरणका लागि अनिवार्य।\\n- नाबालिगका लागि, नागरिकता प्रमाणपत्रको सट्टा जन्म प्रमाणपत्र वा नाबालिग पहिचान कार्ड आवश्यक पर्छ।\\n\\nआवश्यक कागजातहरू\\n- मूल नागरिकता प्रमाणपत्र + फोटोकपी\\n- राष्ट्रिय पहिचान नम्बर (NID/NIN)\\n- पूरा गरिएको अनलाइन प्री-एनरोलमेन्ट फारमको मुद्रित प्रति\\n- पुरानो पासपोर्ट (मूल), यदि नवीकरण/पुनः जारी गरिँदैछ भने\\n- दुई हालसालैको पासपोर्ट आकारको फोटो (सेतो पृष्ठभूमि)\\n- लागू शुल्कको भुक्तानी रसिद/बैंक भौचर\\n- हराइएका पासपोर्टका लागि: पुलिस रिपोर्ट (FIR) र राष्ट्रिय दैनिकमा सूचना\\n- विदेशमा आवेदकहरूका लागि: वैध भिसा/निवास प्रमाणपत्र\\n\\nस्टेप-बाइ-स्टेप प्रक्रिया\\n1. https://emrtds.nepalpassport.gov.np मा अनलाइन प्री‑एनरोलमेंट फारम पूरा गर्नुहोस्।\\n2. आफ्नो रोजाइको कार्यालय चयन गर्नुहोस्: पासपोर्ट विभाग मुख्यालय, कुनै DAO, वा दूतावास/कन्सुलेट।\\n3. नियुक्ति मिति र समय स्लट चयन गर्नुहोस्।\\n4. लागू हुने शुल्क तिर्नुहोस् र आफ्नो प्री‑एनरोलमेंट स्लिप प्रिन्ट गर्नुहोस्।\\n5. नियुक्ति मितिमा सबै मूल कागजातहरू सहित व्यक्तिगत रूपमा उपस्थित हुनुहोस्।\\n6. स्थलमै बायोमेट्रिक क्याप्चर: लाइभ फोटो, औँलाको छाप, र कागजात प्रमाणिकरण।\\n7. प्रक्रिया पूरा हुने प्रतिक्षा गर्नुहोस् (DAO हरूमा सामान्यतया ७–१५ कार्यदिवस; दूतावासहरूमा ४–८ हप्ता)।\\n8. आवेदन गरेको कार्यालयबाट आफ्नो पासपोर्ट सङ्कलन गर्नुहोस्; प्रादेशिक DAO हरूले काठमाडौंबाट यातायातको लागि लगभग ५–७ दिन थप गर्छन्।\\n9. नवीकरण: पुरानो पासपोर्टको सट्टा नयाँ पासपोर्टको लागि आवेदन गर्नुहोस् — वैधता ६ महिना भन्दा कम बाँकी हुँदा सिफारिस गरिन्छ।\\n10. हराएको पासपोर्ट: पुलिस FIR दर्ता गर्नुहोस्, राष्ट्रिय दैनिकमा हराउने सूचना प्रकाशित गर्नुहोस्, त्यसपछि यी कागजातहरूलाई अतिरिक्त कागजातको रूपमा राखी आवेदन गर्नुहोस्।\\n\\nशुल्क (सामान्य नेपाल e‑पासपोर्ट — आधिकारिक साइटमा हालका दरहरू जाँच गर्नुहोस्)\\n- ३४‑पृष्ठ सामान्य: NPR 5,000 | ३४‑पृष्ठ फास्ट‑ट्र्याक: NPR 12,000\\n- ६६‑पृष्ठ सामान्य: NPR 10,000 | ६६‑पृष्ठ फास्ट‑ट्र्याक: NPR 20,000\\n- १० वर्ष मुनिको नाबालिग, ३४‑पृष्ठ: NPR 9,500\\n- विदेशमा: लगभग USD 50–150\\n\\nप्रक्रिया समय\\n- सामान्य: १५–३० कार्यदिवस\\n- तत्काल/फास्ट‑ट्र्याक: २–५ कार्यदिवस\\n- विदेशको दूतावास/कन्सुलेट: ४–८ हप्ता\\n\\nअधिकारिक स्रोतहरू\\n- पासपोर्ट विभाग: https://nepalpassport.gov.np\\n- प्री‑एनरोलमेंट पोर्टल: https://emrtds.nepalpassport.gov.np\\n- विदेश मन्त्रालय: https://mofa.gov.np\\n- आफ्नो रसीद/प्री‑एनरोलमेंट ID प्रयोग गरी आधिकारिक पोर्टलमार्फत पासपोर्ट ट्र्याकिङ गर्नुहोस्\"\n    },\n    \"Driving License\": {\n      \"title\": \"ड्राइभिङ लाइसेन्स\",\n      \"category\": \"परिवहन\",\n      \"description\": \"नेपाली ड्राइभिङ लाइसेन्स Department of Transport Management (DoTM) द्वारा जारी गरिएको। श्रेणीहरू A (मोटरसाइकल) र B (कार)। प्रक्रिया: अनलाइन आवेदन, लिखित परीक्षा, र व्यावहारिक परीक्षण।\",\n      \"guidance\": \"अवलोकन\\nनेपालमा ड्राइभिङ लाइसेन्सहरू मोटर भेहिकल तथा ट्रान्सपोर्ट म्यानेजमेन्ट एक्ट २०४९ अन्तर्गत ट्रान्सपोर्ट म्यानेजमेन्ट विभाग (DoTM) द्वारा जारी गरिन्छ। सामान्य वर्गहरूमा Category A (मोटरसाइकल/स्कूटर) र Category B (कार/जीप) समावेश छन्, तथा व्यावसायिक र भारी सवारी साधनहरूको लागि उच्च वर्गहरू (C, D, E) पनि छन्। प्रक्रिया अनलाइन आवेदन, लिखित परीक्षा, र व्यावहारिक परीक्षण (रोड टेस्ट) समावेश गर्दछ।\\n\\nपूर्वापेक्षाहरू\\n- न्यूनतम उमेर: Category A (मोटरसाइकल) को लागि १६ वर्ष; Category B (कार/जीप) को लागि १८ वर्ष; भारी सवारी वर्गहरू (D, E) को लागि २१ वर्ष।\\n- वैध नागरिकता प्रमाणपत्र धारण गर्नुपर्छ।\\n- लिखित ज्ञान परीक्षण र व्यावहारिक परीक्षण (न्यूनतम ७०/१०० अंक) पास गर्नुपर्छ।\\n- केही उच्च वर्गहरूमा आवेदन गर्नुअघि कम वर्गको लाइसेन्स आवश्यक हुन्छ।\\n\\nआवश्यक कागजातहरू\\n- मूल नेपाली नागरिकता प्रमाणपत्र + फोटोकपी\\n- मान्यताप्राप्त मेडिकल केन्द्र/हस्पिटलबाट रक्त समूह प्रमाणपत्र\\n- दर्ता गरिएको आँखा विशेषज्ञबाट आँखा परीक्षण/दृष्टि प्रमाणपत्र (Category B र माथि)\\n- दर्ता गरिएको डाक्टरबाट मेडिकल/फिटनेस प्रमाणपत्र\\n- दुई हालैको पासपोर्ट साइज फोटो (सेतो पृष्ठभूमि)\\n- राष्ट्रिय परिचयपत्र/NIN — QR स्क्यान मार्फत अनलाइन आवेदनलाई अटो‑फिल गर्न प्रयोग गरिन्छ\\n- लागू हुने सरकारी शुल्कको भुक्तानी रसिद\\n\\nSTEP-BY-STEP PROCEDURE\\n1. DoTM पोर्टल https://applydlnew.dotm.gov.np मा दर्ता/लगइन गर्नुहोस् (वा नागरिक एप मार्फत)।\\n2. आफ्नो प्रोफाइल पूर्ण गर्नुहोस्; NID मा रहेको QR कोड स्क्यान गरेर फारामको धेरै भाग स्वचालित रूपमा भरिनेछ।\\n3. आफ्नो लाइसेन्स वर्ग चयन गर्नुहोस् (मोटरसाइकलको लागि A, कारको लागि B, इत्यादि) — एकैपटक एकभन्दा बढी वर्गको लागि आवेदन गर्न सक्नुहुन्छ।\\n4. आवश्यक कागजातहरू अपलोड गर्नुहोस्: नागरिकता, रक्त समूह प्रमाणपत्र, आँखा परीक्षण प्रमाणपत्र (वर्ग B+), फोटोहरू।\\n5. अनलाइन मार्फत सरकारी शुल्क तिर्नुहोस्।\\n6. तपाईंले रोज्नु भएको ट्रान्सपोर्ट म्यानेजमेन्ट अफिसमा (देशव्यापी कुनै पनि अफिस) अपोइन्टमेन्ट बुक गर्नुहोस्।\\n7. अपोइन्टमेन्ट मितिमा मूल कागजातहरू लिई अफिसमा जानुहोस् प्रमाणिकरण र बायोमेट्रिक दर्ताका लागि।\\n8. अफिसमै लिखित परीक्षा दिनुहोस् (केही क्षेत्रहरूमा कम्प्युटर‑आधारित परीक्षण पनि उपलब्ध हुन सक्छ)।\\n9. पास भएमा, व्यावहारिक परीक्षणको लागि तालिका बनाइनेछ (न्यूनतम ~70 अंक)।\\n10. लिखित परीक्षा पास गरेपछि १८ महिनाभित्र अधिकतम तीन पटक परीक्षणको अवसर पाउनुहुनेछ; तीनै पटक असफल भए ९० दिन पर्खिएर पुन: आवेदन गर्नुपर्छ।\\n11. दुईवटा परीक्षण पास गरेपछि अन्तिम लाइसेन्स जारी शुल्क तिर्नुहोस्।\\n12. स्मार्ट कार्ड प्रिन्ट हुँदै गर्दा अस्थायी ड्राइभिङ स्लिप प्राप्त गर्नुहोस् (तयार भएपछि SMS सुचना) — यो स्लिपले कानुनी रूपमा सवारी चलाउन अनुमति दिन्छ।\\n13. लाइसेन्स अफिसबाट सङ्कलन गर्नुहोस्, वा तपाईंको क्षेत्रमा हावाले डेलिभरी सम्भव छ कि छैन जाँच गर्नुहोस्।\\n\\nSHULK (अनुमानित — वर्तमान दरहरू dotm.gov.np मा जाँच गर्नुहोस्)\\n- मोटरसाइकल/स्कूटर (वर्ग A): लगभग NPR 1,500\\n- कार/जीप (वर्ग B): लगभग NPR 2,000\\n- नवीकरण: समान शुल्क संरचना, प्रत्येक ५ वर्षमा आवश्यक\\n\\nPROCESING TIME\\n- लिखित परीक्षा: कागजात प्रमाणिकरण पछि छिटो नै तालिकाबद्ध गरिन्छ\\n- परीक्षण: लिखित परीक्षा पास गरेपछि तालिकाबद्ध गरिन्छ\\n- स्मार्ट कार्ड प्रिन्टिङ/डेलिभरी: सामान्यतया दुवै परीक्षा पास गरेपछि १५–३० कार्यदिवसभित्र\\n\\nनवीकरण\\n- वैधताको अन्तिम वर्षमा अनलाइन नवीकरण https://applydlnew.dotm.gov.np मा गर्नुहोस्।\\n- ३ महिनाभित्रको मिति भएको नयाँ मेडिकल प्रमाणपत्र (ताजा) र मूल लाइसेन्स आवश्यक पर्छ।\\n- केही कार्यालयहरू अझै व्यक्तिगत भ्रमणको माग गर्न सक्छन्; काठमाडौँका कार्यालयहरू क्रमशः पूर्ण रूपमा अनलाइन हुँदैछन्।\\n\\nअधिकारिक स्रोतहरू\\n- DoTM: https://dotm.gov.np\\n- आवेदन पोर्टल: https://applydlnew.dotm.gov.np\\n- लाइसेन्स प्रमाणिकरण dotm.gov.np मार्फत (DOB + लाइसेन्स नम्बर)\\n- गुनासो/समर्थन: gunaso@dotm.gov.np\"\n    }\n  },\n  \"step_templates\": {\n    \"Citizenship Certificate Copy\": [\n      [\n        \"कागजातहरू सङ्कलन गर्नुहोस्\",\n        \"वार्ड कार्यालयको सिफारिस पत्र, दुवै अभिभावकको नागरिकता प्रमाणपत्र, जन्म दर्ता, विद्यालय/चरित्र प्रमाणपत्र, अभिभावकको विवाह प्रमाणपत्र, दुई पासपोर्ट‑साइज़ फोटो तथा NPR 10 राजस्व टाँस सङ्कलन गर्नुहोस्।\"\n      ],\n      [\n        \"वार्ड कार्यालयको सिफारिस प्राप्त गर्नुहोस्\",\n        \"आफ्नो मूल कागजातहरू सहित नजिकैको वडा कार्यालयमा जानुहोस्। वडा तपाईंको पहिचान र स्थायी बासस्थान प्रमाणित गर्छ, त्यसपछि तपाईंले DAO मा फाइल गर्न सक्नुहुन्छ।\"\n      ],\n      [\n        \"DAO मा आवेदन पेश गर्नुहोस्\",\n        \"Schedule-1 आवेदन फारम भर्नुहोस्, राजस्व टाँस संलग्न गर्नुहोस्, र यसलाई DAO को नागरिकता विभागमा आफ्नो वयस्क साक्षीसँगै पेश गर्नुहोस्।\"\n      ],\n      [\n        \"प्रमाणिकरण र सङ्ग्रह\",\n        \"स्पट इन्क्वायरी (Sarjaamin) कलाइएमा, प्रमाणपत्र लिनुहोस् — प्रायः उही दिन वा केही कार्यदिवसभित्र।\"\n      ]\n    ],\n    \"NID Registration\": [\n      [\n        \"अनलाइन पूर्व‑भर्ना\",\n        \"donidcr.gov.np मा लगइन गर्नुहोस् वा खाता सिर्जना गर्नुहोस् र OTP मार्फत आफ्नो मोबाइल नम्बर प्रमाणित गर्नुहोस्। 'नयाँ दर्ता' सुरु गर्नुहोस् र आफ्नो नागरिकता प्रमाणपत्रसँग ठ्याक्कै मिल्ने विवरणहरू भर्नुहोस्।\"\n      ],\n      [\n        \"कागजात अपलोड गर्नुहोस् र अपोइन्टमेन्ट बुक गर्नुहोस्\",\n        \"आफ्नो नागरिकता प्रमाणपत्र (र वैवाहिक प्रमाणपत्र यदि लागू हुन्छ) अपलोड गर्नुहोस्, आफ्नो दर्ता केन्द्र र भेटघाट मिति चयन गर्नुहोस्, त्यसपछि टोकन स्लिप प्रिन्ट गर्नुहोस्।\"\n      ],\n      [\n        \"बायोमेट्रिक दर्ता\",\n        \"व्यक्तिगत रूपमा उपस्थित हुनुहोस् — अनुहार र कान स्पष्ट रूपमा देखिने गरी। पूर्ण फोटो, दशऔँला फिंगरप्रिन्ट, आईरिस स्क्यान, र डिजिटल हस्ताक्षर; रिपोर्टलाई स्थानमै समीक्षा गर्नुहोस्।\"\n      ],\n      [\n        \"NIN पुष्टि प्राप्त गर्नुहोस्\",\n        \"अस्थायी राष्ट्रिय पहिचान नम्बरको पुष्टि प्राप्त गर्नुहोस्, जुन भौतिक कार्ड छापिँदै गर्दा तुरुन्तै प्रयोग गर्न सकिन्छ।\"\n      ],\n      [\n        \"NID कार्ड सङ्कलन गर्नुहोस्\",\n        \"सूचित गरिएपछि नामांकन केन्द्रबाट आफ्नो भौतिक NID कार्ड सङ्कलन गर्नुहोस् — यो राष्ट्रिय ब्याकलगको आधारमा केही हप्ता देखि केही महिना सम्म लाग्न सक्छ।\"\n      ]\n    ],\n    \"E-Passport Apply\": [\n      [\n        \"पूर्व-नामांकन अनलाइन\",\n        \"तपाईंको नागरिकता र NID विवरणसँगै emrtds.nepalpassport.gov.np मा अनलाइन प्री-एनरोलमेंट फारम पूरा गर्नुहोस्।\"\n      ],\n      [\n        \"कार्यालय चयन गर्नुहोस् र अपोइन्टमेन्ट बुक गर्नुहोस्\",\n        \"पासपोर्ट विभाग मुख्यालय, जिल्ला प्रशासन कार्यालय, वा दूतावास/कन्सुलेट चयन गर्नुहोस्, त्यसपछि नियुक्ति मिति र समय स्लट चयन गर्नुहोस्।\"\n      ],\n      [\n        \"शुल्क तिर्नुहोस् र स्लिप प्रिन्ट गर्नुहोस्\",\n        \"लागु हुने शुल्क तिर्नुहोस् (उदाहरणका लागि, नियमित ३४‑पृष्ठ पासपोर्टको लागि NPR 5,000) र आफ्नो प्रि‑एनरोलमेन्ट स्लिप प्रिन्ट गर्नुहोस्।\"\n      ],\n      [\n        \"बायोमेट्रिक अपोइन्टमेन्टमा उपस्थित हुनुहोस्\",\n        \"सबै मौलिक कागजातहरू सहित व्यक्तिगत रूपमा उपस्थित हुनुहोस्। प्रत्यक्ष फोटो, औँठा छाप र कागजात प्रमाणिकरण साइटमै लिइन्छ।\"\n      ],\n      [\n        \"पासपोर्ट सङ्कलन गर्नुहोस्\",\n        \"तपाईंले आवेदन गरेको कार्यालयबाट आफ्नो पासपोर्ट सङ्ग्रह गर्नुहोस् — DAOs सामान्यतया ७–१५ कार्यदिवस लिन्छन्, दूतावासहरू ४–८ हप्ता।\"\n      ]\n    ],\n    \"Driving License\": [\n      [\n        \"DoTM पोर्टलमा दर्ता गर्नुहोस्\",\n        \"applydlnew.dotm.gov.np मा लगइन गर्नुहोस् (वा नागरिक एप मार्फत) र आफ्नो प्रोफाइल पूरा गर्नुहोस्; आफ्नो NID मा रहेको QR कोड स्क्यान गरेर फारमको धेरै भाग स्वचालित रूपमा भरि लिनुहोस्।\"\n      ],\n      [\n        \"कागजात अपलोड गर्नुहोस् र शुल्क तिर्नुहोस्\",\n        \"नागरिकता, रक्त समूह प्रमाणपत्र, आँखा परीक्षण प्रमाणपत्र (श्रेणी B र माथि), मेडिकल प्रमाणपत्र र फोटोहरू अपलोड गर्नुहोस्, त्यसपछि अनलाइन सरकारी शुल्क तिर्नुहोस्।\"\n      ],\n      [\n        \"बुक र उपस्थित प्रमाणिकरण\",\n        \"आफ्नो रोजेको ट्रान्सपोर्ट म्यानेजमेन्ट अफिसमा अपोइन्टमेन्ट बुक गर्नुहोस् र निर्दिष्ट मितिमा मूल कागजातहरू लिएर प्रमाणिकरण तथा बायोमेट्रिक दर्ता गर्न जानुहोस्।\"\n      ],\n      [\n        \"लेखित परीक्षा पास गर्नुहोस्\",\n        \"कार्यालयमा लिखित ज्ञान परीक्षण दिनुहोस् (केही क्षेत्रहरूमा कम्प्युटर‑आधारित परीक्षण पनि उपलब्ध छ)।\"\n      ],\n      [\n        \"व्यावहारिक परीक्षण पास गर्नुहोस्\",\n        \"यदि तपाईंले लिखित परीक्षा पास गर्नुभयो भने, तपाईंलाई व्यावहारिक परीक्षणको लागि तालिका बनाइन्छ — तपाईंलाई न्यूनतम ~70/100 अंक आवश्यक छ।\"\n      ],\n      [\n        \"लाइसेन्स प्राप्त गर्नुहोस्\",\n        \"अन्तिम जारी शुल्क तिर्नुहोस्, स्मार्ट कार्ड प्रिन्ट हुँदै गर्दा अस्थायी ड्राइभिङ स्लिप प्राप्त गर्नुहोस्, त्यसपछि सूचना प्राप्त भएपछि आफ्नो लाइसेन्स सङ्ग्रह गर्नुहोस् (सामान्यतया १५–३० कार्यदिवस)।\"\n      ]\n    ]\n  },\n  \"default_step_template\": [\n    [\n      \"आवेदन पेश गर्नुहोस्\",\n      \"आफ्नो आवेदन र समर्थन कागजात जिम्मेवार कार्यालयमा पेश गर्नुहोस्।\"\n    ],\n    [\n      \"प्रक्रिया\",\n      \"जिम्मेवार विभागले तपाईंको आवेदनको समीक्षा गरी प्रक्रिया गर्दछ।\"\n    ],\n    [\n      \"संग्रह\",\n      \"प्रक्रिया पूरा भएपछि आफ्नो प्रमाणपत्र/कार्ड/लाइसेन्स सङ्कलन गर्नुहोस्।\"\n    ]\n  ],\n  \"seed_steps\": {\n    \"NID_STEPS\": [\n      [\n        \"NID आवेदन फारम भर्नुहोस्\",\n        \"donidcr.gov.np मा अनलाइन NID आवेदन फारम पूरा गर्नुहोस्। तपाईंलाई आफ्नो नागरिकता नम्बर र हालको पासपोर्ट फोटो आवश्यक पर्छ।\"\n      ],\n      [\n        \"बायोमेट्रिक दर्ता\",\n        \"औँठी छाप र फोटोको लागि आफ्नो नजिकको NID दर्ता केन्द्रमा जानुहोस्। आफ्नो नागरिकता प्रमाणपत्र र आवेदन सन्दर्भ नम्बर ल्याउनुहोस्।\"\n      ],\n      [\n        \"NID कार्ड सङ्कलन गर्नुहोस्\",\n        \"बायोमेट्रिक प्रोसेसिङ (लगभग 30 दिन) पछि, दर्ता केन्द्रबाट आफ्नो NID कार्ड सङ्ग्रह गर्नुहोस्। आफ्नो आवेदन सन्दर्भ नम्बर ल्याउनुहोस्।\"\n      ]\n    ],\n    \"CITIZENSHIP_STEPS\": [\n      [\n        \"DAO मा आवेदन पेश गर्नुहोस्\",\n        \"जिल्ला प्रशासन कार्यालयमा मूल नागरिकता प्रमाणपत्र, २ पासपोर्ट फोटो, र शुल्क रसिदसहित जानुहोस्।\"\n      ],\n      [\n        \"प्रमाणित प्रतिलिपि सङ्कलन\",\n        \"तीन कार्यदिवसपछि फर्केर आफ्नो प्रमाणित नागरिकता प्रतिलिपि लिनुहोस्।\"\n      ]\n    ]\n  }\n}"

